import json
roots={}
for f in ['mcp-hg-slack_conversations_search_messages-1794090611176.txt','mcp-hg-slack_conversations_search_messages-1794090625176.txt']:
  d=json.loads(json.load(open(f))['result'])
  for x in d['messages']:
    if x.get('subtype')=='document_comment_root': roots[x['ts']]=x['text']
print(len(roots))
recs=json.load(open('/tmp/dd/recs.json'))
canon=[r for r in recs if r['src']=='canvas']
rt=[v[2:].strip() for k,v in sorted(roots.items()) if v.strip()]
import re
def norm(s): return re.sub(r'<@EMPLOYEE_0025_SLACK_ID>','@Arthur Blake',re.sub(r'<@EMPLOYEE_0021_SLACK_ID>','@Owen Baker',s)).replace('\xa0',' ').strip()
rt=[norm(x) for x in rt]
mine=[r['title'] for r in canon]
for x in rt:
  if x not in mine: print('MISSING in mine:',repr(x))
print(len(rt))
